const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const contentId = String($json.content_id ?? '').trim();
const title = String($json.title ?? '').trim();
if (!uuidPattern.test(contentId)) {
  throw new Error('Fetch Next Approved Item did not produce a valid content_id. Run the workflow from the start and ensure an idea_approved row exists.');
}
if (!title) {
  throw new Error('Fetch Next Approved Item did not produce a title. Re-run from Manual Trigger and inspect the fetch node output.');
}
return [{
  json: {
    content_id: contentId,
    title,
    category: String($json.category ?? 'general'),
    confidence_label: String($json.confidence_label ?? 'unverified'),
    target_duration_seconds: Number($json.target_duration_seconds ?? 45),
    source_payload_json: $json.source_payload_json ?? {},
    llm_instruction: 'Research this topic and return hook options, narration_script, short_script, caption_draft, and onscreen_text_json.',
    status_after_success: 'script_complete',
    brand_tone: 'cinematic, concise, credible',
    narrator_style: 'calm, serious, engaging',
    ending_signature_family: 'thought-provoking close'
  }
}];

if (!$json.content_id || !$json.title) {
  throw new Error('Prepare Prompt Payload did not pass content_id/title into Build LLM Request.');
}
return [{
  json: {
    content_id: $json.content_id,
    title: $json.title,
    category: $json.category,
    confidence_label: $json.confidence_label,
    target_duration_seconds: $json.target_duration_seconds,
    prompt: {
      instruction: $json.llm_instruction,
      source_payload_json: $json.source_payload_json,
      response_schema: {
        confidence_label: 'confirmed|likely|disputed|legend|unverified',
        hook_option_1: 'string',
        hook_option_2: 'string',
        hook_option_3: 'string',
        selected_hook: 'string',
        narration_script: 'string',
        short_script: 'string',
        caption_draft: 'string',
        cta_line: 'string',
        onscreen_text_json: []
      }
    }
  }
}];

if (!$json.content_id || !$json.title) {
  throw new Error('Build LLM Request did not provide content_id/title to Mock Provider Response.');
}
const sourcePayload = $json.prompt.source_payload_json ?? {};
const sourceNotes = Array.isArray(sourcePayload.notes)
  ? sourcePayload.notes.join(' ')
  : String(sourcePayload.notes ?? sourcePayload.summary ?? '');
const opening = `What if the truth behind ${$json.title} is even stranger than it sounds?`;
const middle = sourceNotes
  ? `Here is what the available notes point to: ${sourceNotes}`
  : `The available notes are still thin, so this version keeps the claim cautious while building tension.`;
const ending = 'The details are real enough to investigate, but uncertain enough to keep people arguing.';
return [{
  json: {
    content_id: $json.content_id,
    title: $json.title,
    status_after_success: $json.status_after_success ?? 'script_complete',
    llm_response: {
      confidence_label: $json.confidence_label || 'unverified',
      hook_option_1: opening,
      hook_option_2: `Most people scroll past ${$json.title}, until they hear the one detail that changes the whole story.`,
      hook_option_3: `This story sounds made up, but the surviving details around ${$json.title} are why it still holds attention.`,
      selected_hook: opening,
      narration_script: `${opening} ${middle} ${ending}`,
      short_script: `${opening} ${ending}`,
      caption_draft: `${$json.title}: a short cinematic breakdown of the details, the uncertainty, and why the story still sticks.`,
      cta_line: 'Would you post the confirmed version or the disputed one?',
      onscreen_text_json: [
        { scene_number: 1, text: $json.title },
        { scene_number: 2, text: 'What the source notes say' },
        { scene_number: 3, text: 'Why people still debate it' }
      ]
    }
  }
}];

const response = $json.llm_response ?? {};
if (!$json.content_id) {
  throw new Error('Mock Provider Response did not provide content_id to Normalize Script Package.');
}
if (!response.selected_hook || !response.narration_script) {
  throw new Error('Mock Provider Response did not produce the expected script fields.');
}
return [{
  json: {
    content_id: $json.content_id,
    title: $json.title,
    status_after_success: $json.status_after_success,
    confidence_label: response.confidence_label,
    hook_option_1: response.hook_option_1,
    hook_option_2: response.hook_option_2,
    hook_option_3: response.hook_option_3,
    selected_hook: response.selected_hook,
    narration_script: response.narration_script,
    short_script: response.short_script,
    caption_draft: response.caption_draft,
    cta_line: response.cta_line,
    onscreen_text_json: response.onscreen_text_json,
    raw_response_json: response
  }
}];

const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const contentId = String($json.content_id ?? '').trim();
if (!uuidPattern.test(contentId)) {
  throw new Error(`Prepare SQL Values received an invalid content_id: ${contentId || '<empty>'}. Re-run from Manual Trigger and verify earlier nodes are not pinned or stale.`);
}
return [{
  json: {
    ...$json,
    content_id_sql: contentId,
    hook_option_1_sql: String($json.hook_option_1 ?? '').replaceAll("'", "''"),
    hook_option_2_sql: String($json.hook_option_2 ?? '').replaceAll("'", "''"),
    hook_option_3_sql: String($json.hook_option_3 ?? '').replaceAll("'", "''"),
    selected_hook_sql: String($json.selected_hook ?? '').replaceAll("'", "''"),
    narration_script_sql: String($json.narration_script ?? '').replaceAll("'", "''"),
    short_script_sql: String($json.short_script ?? '').replaceAll("'", "''"),
    caption_draft_sql: String($json.caption_draft ?? '').replaceAll("'", "''"),
    cta_line_sql: String($json.cta_line ?? '').replaceAll("'", "''"),
    onscreen_text_json_sql: JSON.stringify($json.onscreen_text_json ?? []).replaceAll("'", "''"),
    raw_response_json_sql: JSON.stringify($json.raw_response_json ?? {}).replaceAll("'", "''")
  }
}];
